import sys
from collections import deque
from itertools import combinations

def plain_bfs(n, m, open_cells):
    seen = {(0, 0): 0}
    q = deque([(0, 0)])
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            p = (r + dr, c + dc)
            if p in open_cells and p not in seen:
                seen[p] = seen[(r, c)] + 1
                q.append(p)
    return seen.get((n - 1, m - 1), -1)

def main():
    data = sys.stdin.read().split()
    n, m, k = int(data[0]), int(data[1]), int(data[2])
    grid = data[3:3 + n]
    walls = [(r, c) for r in range(n) for c in range(m) if grid[r][c] == '#']
    base = {(r, c) for r in range(n) for c in range(m) if grid[r][c] == '.'}
    best = -1
    for cnt in range(min(k, len(walls)) + 1):
        for chosen in combinations(walls, cnt):
            d = plain_bfs(n, m, base | set(chosen))
            if d != -1 and (best == -1 or d < best):
                best = d
    print(best)

main()
